import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
def S(doc,name,F,v='image'): save(doc,name,F,'a',verified=v)

S('0221',"آلية امتحان القبول في تخصصات كلية العمارة والتصميم",[
("number",[1],"البند 1 و2","يشترط للتقدم لتخصصي العمارة والتخطيط الحضري وتخطيط المدن أن يكون الطالب حاصلاً على الثانوية العامة بالفرع العلمي، ويحق لكل طالب حاصل على معدل في الثانوية العامة 80% أو ما يعادلها التقدم لامتحان القبول المعد لهذه الغاية، ويعلن عنه على موقع الجامعة وفي الصحف المحلية.",
 "ما شروط التقدم لامتحان القبول في تخصصي العمارة والتخطيط الحضري وتخطيط المدن؟","ما أدنى معدل في الثانوية العامة للتقدم لامتحان القبول في كلية العمارة والتصميم؟","شو الشروط عشان أقدم على امتحان قبول العمارة؟"),
("number",[1],"البند 3","يتم تعبئة النموذج الخاص للالتحاق في تخصصات كلية العمارة والتصميم في وحدة القبول والتسجيل بعد دفع رسم طلب الالتحاق ويقترح أن يكون المبلغ (50 ديناراً).",
 "كم رسم طلب الالتحاق لامتحان قبول كلية العمارة والتصميم؟","أين يعبأ نموذج الالتحاق لتخصصات كلية العمارة والتصميم؟","كم بدفع عشان أقدم لامتحان العمارة؟"),
("rule",[1],"البند 5","يتضمن امتحان القبول الخاص بكل قسم من أقسام كلية العمارة والتصميم امتحان قدرات ومقابلة شخصية وأي محاور تحدد بقرار من مجلس الكلية لاحقاً.",
 "ماذا يتضمن امتحان القبول في كلية العمارة والتصميم؟","هل في مقابلة شخصية ضمن قبول العمارة؟","شو بيكون بامتحان قبول العمارة؟"),
("number",[1],"البند 6","تحدد نسبة 50% من علامة القبول لهذا الامتحان فيما تحتسب الـ 50% الباقية لعلامة الطالب في الثانوية العامة.",
 "ما نسبة امتحان القبول من علامة القبول في كلية العمارة والتصميم؟","كم نسبة علامة الثانوية العامة في احتساب علامة القبول لتخصصات العمارة؟","كيف بتتوزع علامة القبول بالعمارة بين الامتحان والتوجيهي؟"),
("number",[1],"البندان الأخيران","يتم تصحيح الامتحان من قبل اللجان المشكلة لهذه الغاية وتزويد وحدة القبول والتسجيل بالنتائج خلال 72 ساعة من عقد الامتحان بعد مصادقة عمادة كلية العمارة والتصميم ورئاسة الجامعة، وتعتبر النتائج بعد ذلك قطعية. وتعلن وحدة القبول والتسجيل النتائج وأسماء الطلبة المقبولين خلال 24 ساعة من استلامها النتائج المصادق عليها.",
 "خلال كم ساعة تعلن نتائج امتحان قبول كلية العمارة والتصميم؟","من يعلن أسماء المقبولين بعد امتحان القبول في كلية العمارة والتصميم؟","متى بتطلع نتيجة امتحان قبول العمارة؟"),
])

S('0231',"تعليمات عقد امتحان الإكمال لطلبة كلية العمارة والتصميم",[
("rule",[1],"أولاً","يعقد امتحان الإكمال لمساقات كلية العمارة والتصميم: مبادئ التصميم (1) و(2)، وتصميم معماري (1) إلى (6)، ومرسم تخطيط حضري 1 و2، ومرسم تصميم حضري 1 و2، التي رسب بها وهي «متطلب سابق نجاح» لمساقات عملية أخرى في الخطط الفعالة للكلية، اعتباراً من نهاية الفصل الدراسي الأول من العام الجامعي 2025/2024.",
 "لأي مساقات في كلية العمارة والتصميم يعقد امتحان الإكمال؟","ما المساقات التي يتقدم لها الطالب بامتحان الإكمال في العمارة والتصميم؟","أي مساقات بالعمارة فيها امتحان إكمال؟"),
("number",[1],"ثانياً","يشترط للتقدم لامتحان الإكمال ألا يكون الطالب محروماً بسبب الغياب أو بسبب عقوبة تأديبية، والحد الأقصى لعدد مرات التقدم لامتحان الإكمال هو مرتان خلال فترة الدراسة بغض النظر عن عدد المساقات، ويجوز للطالب التقدم لامتحان الإكمال للمرة الثانية للمساق الواحد بعد الرسوب به للمرة الثانية في فصلين دراسيين مختلفين، ويقدم الطالب طلب التقدم إلكترونياً إلى عميد الكلية خلال فترة إتاحة الطلبات المعلنة.",
 "كم مرة يمكن للطالب التقدم لامتحان الإكمال في كلية العمارة والتصميم خلال دراسته؟","ما شروط التقدم لامتحان الإكمال في كلية العمارة والتصميم؟","كم مرة بقدر أقدم إكمال بالعمارة؟"),
("number",[1],"ثالثاً","الحد الأدنى لعلامة النجاح في امتحان الإكمال 50%، ويرصد للطالب الناجح الرمز (D-) في سجله الأكاديمي بغض النظر عن العلامة التي حصل عليها. وتبقى علامة الطالب الراسب كما كانت عليه في سجله الأكاديمي قبل التقدم للامتحان وعليه إعادة دراسة المساق، ولا يجوز التقدم بطلب مراجعة علامة للعلامة الأصلية للمساق بعد التقدم لامتحان الإكمال والرسوب به.",
 "كم علامة النجاح في امتحان الإكمال بكلية العمارة والتصميم وما الرمز الذي يرصد؟","ماذا يحدث لعلامة الطالب إذا رسب في امتحان الإكمال؟","شو العلامة اللي بتنحسب اذا نجحت بامتحان الإكمال؟"),
("rule",[1],"رابعاً","يعقد الامتحان في موعد أقصاه الأسبوع الأول من بدء التدريس للفصل الدراسي اللاحق لفصل الرسوب، ويفقد الطالب حقه في التقدم للامتحان في حال عدم تقدمه بطلب خلال الفترة المعلنة من الكلية أو تأجيله للدراسة للفصل اللاحق لفصل الرسوب.",
 "متى يعقد امتحان الإكمال في كلية العمارة والتصميم؟","متى يفقد الطالب حقه في التقدم لامتحان الإكمال؟","اذا نسيت أقدم على امتحان الإكمال شو بصير؟"),
])

S('0233',"تعليمات الدراسة والعبء الدراسي في الفصل الدراسي الصيفي",[
("number",[1],"المادة 3","مدة الفصل الدراسي الصيفي ثمانية أسابيع دراسية بما في ذلك فترة الامتحانات ويقرر مجلس العمداء التقويم الخاص بذلك.",
 "كم مدة الفصل الدراسي الصيفي؟","هل تدخل فترة الامتحانات ضمن مدة الفصل الصيفي؟","كم أسبوع الفصل الصيفي؟"),
("rule",[1],"المادة 4","تنظم العمادات المعنية عملية طرح المواد في الفصل الصيفي بالتنسيق مع وحدة القبول والتسجيل، والفصل الدراسي الصيفي اختياري لطلبة الجامعة ما لم تذكر الخطة الدراسية لبعض التخصصات خلاف ذلك، ويجوز للعمادات المعنية إلغاء الشعب والمواد بعد طرحها حسب ما تراه لمصلحة الجامعة.",
 "هل الفصل الصيفي إجباري على طلبة الجامعة؟","من ينظم طرح المواد في الفصل الصيفي؟","لازم أدرس صيفي؟"),
("number",[1],"المادة 5","لا يزيد العبء الدراسي للطالب المسجل في الفصل الدراسي الصيفي على (10) ساعات معتمدة في أي حال من الأحوال. ويجوز للطالب أن يسجل أي عبء دراسي أقل أو يساوي (10) ساعات معتمدة ولا يجبر الجامعة على تحديد عبئه الدراسي. وتفويض عمداء الكليات السماح للطلبة المتوقع تخرجهم في نهاية الفصل الصيفي بدراسة (12) ساعة معتمدة كحد أعلى على ألا يزيد العبء الدراسي في الجامعة عن (10) ساعات، ويمكن للطالب دراسة ما لا يزيد عن (3) ساعات في خارج الجامعة وبموافقة العميد المسبقة.",
 "كم الحد الأقصى للساعات المعتمدة التي يسجلها الطالب في الفصل الصيفي؟","هل يسمح للمتوقع تخرجه بتسجيل أكثر من 10 ساعات في الصيفي؟","كم ساعة بقدر أسجل صيفي؟"),
("number",[1],"المادة 6","الحد الأدنى لأعداد الطلبة لشعب المواد المطروحة في الفصل الصيفي: المواد من متطلبات الجامعة (40) طالباً، والمواد من متطلبات الكلية (25) طالباً، والمواد من متطلبات التخصص (20) طالباً، والمواد العملية (المختبرات) (10) طلاب أو سعة المختبر.",
 "كم الحد الأدنى لعدد الطلبة في شعبة مادة من متطلبات الجامعة في الفصل الصيفي؟","كم الحد الأدنى لعدد الطلبة لشعبة مختبر في الصيفي؟","كم طالب لازم يسجل عشان تنفتح شعبة صيفي؟"),
("rule",[1],"المادة 7","تلغى بقرار من العميد المعني وبالتنسيق مع وحدة القبول والتسجيل جميع المواد والشعب التي لا تتناسب أعداد الطلبة المسجلين بها مع تلك الأعداد المبينة بالمادة (6)، وذلك قبل بداية الفصل الدراسي الصيفي بأسبوع على الأقل، ويعلن عن ذلك للطلبة من قبل الكليات والأقسام ووحدة القبول والتسجيل.",
 "متى تلغى الشعب التي لا يكتمل عدد طلبتها في الفصل الصيفي؟","من يملك قرار إلغاء الشعب في الفصل الصيفي؟","اذا ما اكتمل عدد الطلاب بالشعبة الصيفية شو بصير؟"),
])

S('0237',"لائحة التفوق الفصلي الأكاديمي",[
("rule",[1],"المادة 1 و2 و3","يحتسب المعدل التراكمي من نتائج المساقات التي هي من ضمن الخطة الدراسية كمتطلبات قسم أو كلية أو متطلبات جامعة على أن تدخل أفضل نتائج لتسع ساعات معتمدة فقط من متطلبات الجامعة الاختيارية في المعدل، ويجري حساب أي من المعدلات السابقة بضرب علامة كل مساق محتسب في المعدل في عدد ساعاته المعتمدة وقسمة مجموع حواصل الضرب الناتجة على مجموع الساعات المعتمدة، وتحسب كل المعدلات لأقرب منزلة عشرية واحدة.",
 "كيف يحسب المعدل التراكمي لغايات لائحة التفوق؟","كم ساعة من متطلبات الجامعة الاختيارية تدخل في المعدل؟","كيف بنحسب معدلي بلائحة التفوق؟"),
("number",[1],"المادة 4","يعتبر الطالب الأول في القسم أو الكلية هو الطالب الحاصل على أعلى معدل على دفعته، شريطة ألا تزيد مدة الدراسة الفعلية على: 6 سنوات لكلية الطب ودرجة دكتور صيدلة، و5 سنوات لكليات الهندسة وطب الأسنان والطب البيطري وتخصص هندسة الحاسوب وتخصص الصيدلة، و4 سنوات لكليات التمريض والزراعة والعلوم والآداب وتخصصي علوم الحاسوب ونظم المعلومات الحاسوبية وكلية العلوم الطبية التطبيقية.",
 "ما أقصى مدة دراسة فعلية ليعتبر الطالب الأول على الدفعة في كلية الهندسة؟","كم سنة يشترط ألا تزيد دراسة الطالب ليكون الأول على دفعته في كلية الطب؟","كم سنة لازم أخلص عشان أكون الأول على الدفعة؟"),
("number",[1],"المادة 5 و6","يضع العميد اسم الطالب الذي يحصل على معدل فصلي مقداره (85%) فأكثر على لائحة شرف الكلية ويثبت في سجله الأكاديمي، ما لم يكن سبق وكان مفصولاً أو موضوعاً تحت المراقبة الأكاديمية، ولا يقل العبء الدراسي عن (12) ساعة معتمدة. ويصدر رئيس الجامعة لائحة شرف الجامعة فصلياً وتتضمن أسماء الطلبة الذين حصلوا على معدلات فصلية مقدارها (90%) فأكثر من بين المسجلين على لوائح شرف الكليات.",
 "ما المعدل الفصلي المطلوب للدخول في لائحة شرف الكلية؟","ما المعدل الفصلي المطلوب للدخول في لائحة شرف الجامعة؟","كم لازم يكون معدلي عشان أنحط بلائحة الشرف؟"),
])

S('0227',"قرارات خاصة بالفصل الإضافي",[
("rule",[1],"القرار 1","الطلبة الذين يفصلون في نهاية الفصل الثاني يعطون الفصل الصيفي والأول لرفع معدلاتهم، والطلبة الذين يفصلون في نهاية الفصل الأول يعطون الفصل الثاني والصيفي. والطلبة الذين يفصلون في نهاية الفصل الأول ولم يسجلوا الفصل الثاني وأخذوا الفصل الصيفي والأول الذي يليه يعتبرون منقطعين عن الدراسة. ومن يفصل بأثر رجعي يتم استيفاء فرق الرسوم منه (من العادي للموازي).",
 "ما الفصول التي يعطاها الطالب المفصول في نهاية الفصل الثاني لرفع معدله؟","ما الفصول الإضافية التي يعطاها الطالب المفصول في نهاية الفصل الأول؟","اذا انفصلت آخر الفصل التاني، كم فصل إضافي بياخدوه؟"),
("rule",[1],"القرار 3","طلبة المكرمة الملكية الذين يفصلون من التخصص ويتم إعطاؤهم فصل إضافي بالبرنامج الموازي يكون هذا الفصل على حسابهم الخاص ويستمر بدفع الرسوم على حسابهم الخاص لحين التخرج، وتكون تسوية الأمور المالية عن طريق المكرمة الملكية.",
 "على حساب من يكون الفصل الإضافي لطلبة المكرمة الملكية المفصولين من التخصص؟","هل يتحمل طالب المكرمة الملكية رسوم الفصل الإضافي في الموازي؟","اذا انفصلت وأنا من طلاب المكرمة، مين بدفع الفصل الإضافي؟"),
])

S('0219',"تعليمات امتحان الإكمال للطلبة الراسبين في مساقات التدريب الصيدلاني في الصيدليات",[
("number",[1],"المقدمة","يحق للطالب التقدم إلى امتحان الإكمال لمرة واحدة فقط في المساق الذي رسب فيه وبدون إعادة التدريب بشرط أن يكون الرسوب بعلامة لا تقل عن 40% والحصول على مجموع أعمال فصلية لا يقل عن (50%) من مجموع علامات الأعمال الفصلية المخصصة لها وألا يكون الطالب محروماً بسبب عقوبة تأديبية، وذلك في مساقات التدريب الصيدلاني في الصيدليات.",
 "ما شروط التقدم لامتحان الإكمال في مساقات التدريب الصيدلاني؟","كم مرة يحق للطالب التقدم لامتحان الإكمال في مساق التدريب الصيدلاني؟","شو شروط امتحان الإكمال بالتدريب الصيدلاني؟"),
("number",[1],"البند 5 و6","الحد الأدنى لعلامة النجاح في امتحان الإكمال هو (50%)، ويرصد الرمز المقابل لعلامة الامتحان لكل علامة أقل من (60%)، وتثبت علامة (60%) برمز (ج-) كعلامة نهائية مستحقة لكل علامة امتحان مابين (60-100)، وتبقى علامة الطالب الراسب في امتحان الإكمال كما كانت عليه في سجله الأكاديمي وعليه إعادة دراسة مساق التدريب الصيدلاني.",
 "كم علامة النجاح في امتحان الإكمال لمساقات التدريب الصيدلاني؟","ماذا يحدث لعلامة الطالب الراسب في امتحان الإكمال للتدريب الصيدلاني؟","كم بتنحسب علامتي لو نجحت بامتحان الإكمال؟"),
("rule",[1],"البند 3 و4","يعقد الامتحان في موعد أقصاه نهاية الأسبوع الثالث من بدء التدريس للفصل الدراسي اللاحق لفصل الرسوب، ويفقد الطالب حقه في التقدم في حال عدم تقدمه بطلب خلال الفترة المعلنة من الكلية أو تأجيله للدراسة للفصل الدراسي اللاحق لفصل الرسوب.",
 "متى يعقد امتحان الإكمال لمساقات التدريب الصيدلاني؟","متى يفقد طالب الصيدلة حقه بامتحان الإكمال؟","متى بصير امتحان الإكمال للصيدلة؟"),
])
